import { loadFont } from "@remotion/google-fonts/Arimo";
import React from "react";
import { AbsoluteFill, Easing, Img, Loop, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// ACADEMIA FALCON — vídeo para a TV da academia (5 min, horizontal 1920×1080, sem locução, feito para ficar em repetição).
// Abertura → estrutura (musculação, piscina) → cada uma das 7 artes da cliente refeita em motion (migre para o anual,
// indique um amigo, hidroginástica, natação adulto, natação infantil, Dia das Crianças, ritmos) → resumo → logo.
// Identidade das artes dela: preto, vermelho e branco, título em itálico caixa-alta com a palavra-chave numa tarja branca
// inclinada, faixas diagonais; azul nas modalidades aquáticas e roxo no bloco de ritmos, como nas artes.
// Regras: limpo, texto entra e fica parado, movimento nas imagens/faixas, transições variadas, clipes verticais inteiros.

const { fontFamily: FI } = loadFont("italic", { weights: ["700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: FN } = loadFont("normal", { weights: ["700"], subsets: ["latin", "latin-ext"] });

export const FTV_FPS = 30;
export const FTV_FRAMES = 300 * FTV_FPS;
const RED = "#D4000F";
const WHITE = "#FFFFFF";
const INK = "#0B0B0B";

type ThemeKey = "red" | "blue" | "pool" | "purple";
const TH: Record<ThemeKey, { bg: string; accent: string; tagFg: string; stripe: string[]; card: string; bar: string; barFg: string }> = {
  red: { bg: "linear-gradient(100deg, #0A0A0A 0%, #12060A 55%, #2A0006 100%)", accent: RED, tagFg: RED, stripe: ["#D4000F", "#5C0009", "#8E000C"], card: "#101010", bar: RED, barFg: WHITE },
  blue: { bg: "linear-gradient(100deg, #041E4A 0%, #063A78 55%, #0A86C4 100%)", accent: "#00B4DC", tagFg: "#0A73B7", stripe: ["#1FC3E6", "#0A5FA8", "#0FA0D2"], card: "#00B4DC", bar: "#00B4DC", barFg: "#062A56" },
  pool: { bg: "linear-gradient(180deg, #0786C6 0%, #1AA6DC 60%, #3CC3E6 100%)", accent: "#053E7C", tagFg: "#0A73B7", stripe: ["#5ED2F0", "#0F8FD0", "#2FB4E4"], card: "#053E7C", bar: WHITE, barFg: "#062A56" },
  purple: { bg: "radial-gradient(ellipse 70% 80% at 72% 45%, #5A0A8E 0%, #2A0458 55%, #150230 100%)", accent: "#FF2D8E", tagFg: WHITE, stripe: ["#FF2D8E", "#FFB000", "#B01FA0"], card: "#2A0458", bar: WHITE, barFg: "#1B0635" },
};

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.4));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const fromLeft = (t: number, at: number, dx = 220): React.CSSProperties => {
  const e = k(t, at);
  return { opacity: Math.min(1, e * 2.5), transform: `translateX(${((1 - e) * -dx).toFixed(1)}px)` };
};
const fromRight = (t: number, at: number, dx = 320): React.CSSProperties => {
  const e = interpolate(t, [at, at + 0.55], [0, 1], { ...cl, easing: BACK });
  return { opacity: interpolate(t, [at, at + 0.2], [0, 1], cl), transform: `translateX(${((1 - e) * dx).toFixed(1)}px)` };
};
const rise = (t: number, at: number, dy = 50): React.CSSProperties => {
  const e = k(t, at);
  return { opacity: e, transform: `translateY(${((1 - e) * dy).toFixed(1)}px)` };
};
const slam = (t: number, at: number): React.CSSProperties => {
  const e = k(t, at, 0.28);
  return { opacity: t >= at ? Math.min(1, e * 3) : 0, transform: `scale(${(1.5 - 0.5 * e).toFixed(3)})`, transformOrigin: "0% 60%" };
};
const zoom = (t: number, at: number): React.CSSProperties => ({ opacity: t >= at ? 1 : 0, transform: `scale(${pop(t, at).toFixed(3)})` });
const it = (size: number, color = WHITE): React.CSSProperties => ({ fontFamily: FI, fontStyle: "italic", fontWeight: 700, fontSize: size, lineHeight: 1, color, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "-0.01em" });
const nb = (size: number, color = WHITE): React.CSSProperties => ({ fontFamily: FN, fontWeight: 700, fontSize: size, lineHeight: 1.36, color });

// ───────── fundos ─────────
const Stripes: React.FC<{ t: number; theme: ThemeKey; alpha?: number }> = ({ t, theme, alpha = 1 }) => {
  const c = TH[theme].stripe;
  const d = Math.sin(t * 0.35) * 40;
  return (
    <AbsoluteFill style={{ opacity: alpha, overflow: "hidden" }}>
      {[
        [1640, 200, c[0], 1],
        [1380, 110, c[1], 0.9],
        [1160, 70, c[1], 0.55],
        [1880, 260, c[2], 0.5],
      ].map(([x, w, col, o], i) => (
        <div key={i} style={{ position: "absolute", left: (x as number) + d * (i % 2 ? 1 : -1), top: -200, width: w as number, height: 1500, background: col as string, opacity: o as number, transform: "skewX(-28deg)", overflow: "hidden" }}>
          <div style={{ position: "absolute", left: 0, right: 0, height: 620, top: -620 + ((t * (0.22 + i * 0.05) + i * 0.31) % 1) * 2200, background: "linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.34) 50%, rgba(255,255,255,0) 100%)" }} />
        </div>
      ))}
    </AbsoluteFill>
  );
};
const Waves: React.FC<{ t: number; light?: boolean }> = ({ t, light }) => (
  <svg width={1920} height={220} viewBox="0 0 1920 220" style={{ position: "absolute", left: 0, bottom: 0 }}>
    {[0, 1, 2].map((i) => {
      const ph = t * (0.8 + i * 0.3) + i * 2;
      let d = `M0 ${90 + i * 40}`;
      for (let x = 0; x <= 1920; x += 120) d += ` Q${x + 60} ${90 + i * 40 + Math.sin(ph + x / 260) * 34} ${x + 120} ${90 + i * 40 + Math.sin(ph + (x + 120) / 260) * 16}`;
      return <path key={i} d={`${d} L1920 220 L0 220 Z`} fill={light ? "#BFEAF7" : "#7FD8F2"} opacity={0.18 + i * 0.12} />;
    })}
  </svg>
);
const Bg: React.FC<{ t: number; theme: ThemeKey }> = ({ t, theme }) => (
  <AbsoluteFill style={{ background: TH[theme].bg, overflow: "hidden" }}>
    {theme === "purple" ? null : <Stripes t={t} theme={theme} alpha={theme === "pool" ? 0.35 : 1} />}
    {theme === "blue" || theme === "pool" ? <Waves t={t} light={theme === "pool"} /> : null}
    {theme === "blue" || theme === "pool"
      ? [0, 1, 2].map((i) => {
          const u = (t * 0.22 + i / 3) % 1;
          return <div key={i} style={{ position: "absolute", left: 300 - 420, top: 500 - 420, width: 840, height: 840, borderRadius: "50%", border: "3px solid rgba(255,255,255,0.22)", opacity: 0.7 * (1 - u), transform: `scale(${(0.25 + u * 0.9).toFixed(3)})` }} />;
        })
      : null}
    {theme === "pool" ? (
      <div style={{ position: "absolute", left: 0, top: 6, width: 1920 + 240, height: 34, display: "flex", transform: `translateX(${(-((t * 40) % 120)).toFixed(1)}px)` }}>
        {Array.from({ length: 54 }, (_, i) => (
          <div key={i} style={{ width: 34, height: 22, marginRight: 6, marginTop: 6, borderRadius: 11, background: [WHITE, "#0B3C8C", "#E63946"][i % 3] }} />
        ))}
      </div>
    ) : null}
  </AbsoluteFill>
);

// ───────── peças ─────────
const Logo: React.FC<{ w: number; style?: React.CSSProperties }> = ({ w, style }) => <Img src={staticFile("falcontv/logo.png")} style={{ width: w, display: "block", ...style }} />;
// duração de cada clipe (s): se o clipe é mais curto que o tempo em tela, toca um pouco mais lento e, se preciso, repete
const DUR: Record<string, number> = { f1: 5.27, f2: 4.87, f3: 3.77, g1: 4.97, g2: 5.17, g3: 3.53, g4: 5.17, g5: 5.17, g7: 6.6, g8: 4.93, g9: 5.43, g10: 5.0, g11: 4.8, g12: 3.17, p1: 6.43, p2: 8.87, p3: 5.63, p4: 6.3, p5: 6.43, p6: 5.03 };
// clipe vertical inteiro dentro de uma moldura
const Frame: React.FC<{ t: number; src: string; start: number; x: number; y: number; w: number; rot?: number; enter: number; exit: number; color?: string; from?: "bottom" | "top" }> = ({ t, src, start, x, y, w, rot = 0, enter, exit, color = WHITE, from = "bottom" }) => {
  if (t < enter - 0.05 || t > exit + 0.5) return null;
  const e = interpolate(t, [enter, enter + 0.6], [0, 1], { ...cl, easing: OUT });
  const o = interpolate(t, [exit, exit + 0.45], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
  const dy = (1 - e) * (from === "bottom" ? 1200 : -1200) + o * (from === "bottom" ? -1300 : 1300);
  const h = (w * 16) / 9;
  const rate = Math.max(0.78, Math.min(1, ((DUR[src] ?? 5) - 0.15) / (exit + 0.5 - start)));
  return (
    <div style={{ position: "absolute", left: x, top: y, width: w, height: h, borderRadius: 26, overflow: "hidden", border: `6px solid ${color}`, boxSizing: "border-box", background: "#000", boxShadow: "0 30px 70px rgba(0,0,0,0.55)", transform: `translateY(${dy.toFixed(0)}px) rotate(${rot}deg)` }}>
      <Sequence from={Math.round(start * FTV_FPS)} layout="none">
        <Loop durationInFrames={Math.max(30, Math.floor(((DUR[src] ?? 5) - 0.15) / rate * FTV_FPS))} layout="none">
          <OffthreadVideo src={staticFile(`falcontv/${src}.mp4`)} muted playbackRate={rate} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${(1.02 + 0.06 * lin(t, enter, exit)).toFixed(4)})` }} />
        </Loop>
      </Sequence>
    </div>
  );
};
// foto inteira (3:4) numa moldura, com aproximação lenta
const Foto: React.FC<{ t: number; src: string; x: number; y: number; w: number; enter: number; exit: number }> = ({ t, src, x, y, w, enter, exit }) => {
  if (t < enter - 0.05 || t > exit + 0.5) return null;
  const e = interpolate(t, [enter, enter + 0.6], [0, 1], { ...cl, easing: OUT });
  const o = interpolate(t, [exit, exit + 0.45], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
  return (
    <div style={{ position: "absolute", left: x, top: y, width: w, height: (w * 4) / 3, borderRadius: 26, overflow: "hidden", border: `6px solid ${WHITE}`, boxSizing: "border-box", background: "#000", boxShadow: "0 30px 70px rgba(0,0,0,0.55)", transform: `translateY(${((1 - e) * 1200 - o * 1300).toFixed(0)}px) rotate(-1.5deg)` }}>
      <Img src={staticFile(`falcontv/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${(1.0 + 0.05 * lin(t, enter, exit)).toFixed(4)})` }} />
    </div>
  );
};
const Trip: React.FC<{ t: number; clips: string[]; a: number; b: number; x?: number; y?: number; w?: number; color?: string }> = ({ t, clips, a, b, x = 1000, y = 190, w = 262, color }) => (
  <>
    {clips.map((c, i) => (
      <Frame key={c + a} t={t} src={c} start={a} x={x + i * (w + 30)} y={y + [26, 0, 26][i % 3]} w={w} rot={[-2.5, 0, 2.5][i % 3]} enter={a + i * 0.14} exit={b + i * 0.08} color={color} from={i % 2 ? "top" : "bottom"} />
    ))}
  </>
);
// bloco de título das artes: chamada, palavra grande, palavra-chave na tarja inclinada, frase
const Title: React.FC<{ t: number; a: number; theme: ThemeKey; top: number; kicker?: string; big: string; bigSize?: number; tag?: string; tagSize?: number; body?: string; tagBg?: string; tagFg?: string; glow?: boolean; mid?: string }> = ({ t, a, theme, top, kicker, big, bigSize = 190, tag, tagSize, body, tagBg = WHITE, tagFg, glow, mid }) => {
  const ts = tagSize ?? bigSize * 0.86;
  const tw = k(t, a + 1.25, 0.4);
  return (
    <div style={{ position: "absolute", left: 80, top, width: 900 }}>
      {kicker ? <div style={{ ...it(Math.min(54, 860 / (kicker.length * 0.61))), marginBottom: 14, ...fromLeft(t, a + 0.35) }}>{kicker}</div> : null}
      <div style={{ ...it(bigSize), textShadow: glow ? "0 0 26px rgba(255,255,255,0.55)" : "none", ...slam(t, a + 0.75) }}>{big}</div>
      {mid ? <div style={{ ...it(46, "#FFB000"), marginTop: 30, ...fromLeft(t, a + 1.1) }}>{mid}</div> : null}
      {tag ? (
        <div style={{ display: "inline-block", marginTop: mid ? 10 : 6, marginLeft: -8, background: tagBg, transform: `skewX(-8deg) scaleX(${tw.toFixed(3)})`, transformOrigin: "0% 50%", padding: `${ts * 0.04}px ${ts * 0.2}px ${ts * 0.08}px` }}>
          <div style={{ ...it(ts, tagFg ?? TH[theme].tagFg), transform: "skewX(8deg)", opacity: lin(t, a + 1.45, a + 1.65) }}>{tag}</div>
        </div>
      ) : null}
      {body ? <div style={{ ...nb(37), width: 780, marginTop: 44, ...rise(t, a + 2.0) }}>{body}</div> : null}
    </div>
  );
};
// faixa inclinada de chamada (embaixo)
const Bar: React.FC<{ t: number; at: number; full?: boolean; bg: string; children: React.ReactNode; top?: number; h?: number; edge?: string }> = ({ t, at, full, bg, children, top = 830, h = 140, edge }) => {
  const e = k(t, at, 0.6);
  return (
    <div style={{ position: "absolute", left: full ? 60 : 70, top, width: full ? 1800 : 830, height: h, background: bg, transform: `skewX(-6deg) scaleX(${e.toFixed(3)})`, transformOrigin: "0% 50%", borderBottom: edge ? `8px solid ${edge}` : undefined, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ transform: "skewX(6deg)", opacity: lin(t, at + 0.35, at + 0.6), textAlign: "center" }}>{children}</div>
    </div>
  );
};
// cartão da coluna da direita, com um reflexo de luz passando de vez em quando
const Card: React.FC<{ t: number; at: number; top: number; h: number; kind: "dark" | "solid" | "white" | "whiteL"; theme: ThemeKey; children: React.ReactNode; left?: number; w?: number; pad?: string }> = ({ t, at, top, h, kind, theme, children, left = 990, w = 860, pad = "0 40px" }) => {
  const th = TH[theme];
  const bg = kind === "dark" ? "#101010" : kind === "solid" ? (theme === "red" ? `linear-gradient(100deg, ${RED} 0%, ${RED} 60%, #A8000C 100%)` : th.card) : WHITE;
  const sw = ((t - at + left * 0.001) % 3.4) / 0.9;
  const beat = kind === "solid" && t > at + 2 ? Math.max(0, 1 - ((t - at) % 4) / 0.45) : 0;
  return (
    <div style={{ position: "absolute", left, top, width: w, height: h, borderRadius: 22, background: bg, border: kind === "dark" ? `3px solid ${th.accent}` : "none", borderLeft: kind === "whiteL" ? `18px solid ${th.accent}` : kind === "dark" ? `3px solid ${th.accent}` : "none", borderBottom: kind === "solid" || kind === "white" ? `10px solid rgba(0,0,0,0.28)` : undefined, boxSizing: "border-box", overflow: "hidden", padding: pad, display: "flex", flexDirection: "column", justifyContent: "center", opacity: fromRight(t, at).opacity, transform: `${fromRight(t, at).transform} scale(${(1 + 0.035 * beat * beat).toFixed(4)})` }}>
      {children}
      {t > at + 1 && sw < 1 ? <div style={{ position: "absolute", top: -40, bottom: -40, width: 160, left: -200 + sw * (w + 300), background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.22) 50%, rgba(255,255,255,0) 100%)", transform: "skewX(-20deg)" }} /> : null}
    </div>
  );
};
const Price: React.FC<{ pre: string; value: string; size?: number; color?: string }> = ({ pre, value, size = 190, color = WHITE }) => (
  <div style={{ display: "flex", alignItems: "baseline", gap: 14 }}>
    <div style={it(size * 0.3, color)}>{pre}</div>
    <div style={{ ...it(size, color), letterSpacing: "-0.03em" }}>{value}</div>
  </div>
);

// troca de bloco: quatro tipos, alternados
type Kind = "skew" | "up" | "iris" | "split";
const Cut: React.FC<{ t: number; at: number; i: number; color: string; edge: string; kind: Kind }> = ({ t, at, i, color, edge, kind }) => {
  const d = 0.3;
  if (t < at - d || t > at + d) return null;
  const dir = i % 2 ? -1 : 1;
  if (kind === "up") return <div style={{ position: "absolute", left: -100, top: -100, width: 2120, height: 1280, background: color, transform: `translateY(${((1 - lin(t, at - d, at + d) * 2) * 1400 * dir).toFixed(0)}px)`, boxShadow: `0 24px 0 ${edge}, 0 -24px 0 ${edge}` }} />;
  if (kind === "iris") return t < at ? <div style={{ position: "absolute", left: 960 - 1200, top: 540 - 1200, width: 2400, height: 2400, borderRadius: 1200, background: color, boxShadow: `0 0 0 22px ${edge}`, transform: `scale(${interpolate(t, [at - d, at], [0, 1], { ...cl, easing: Easing.in(Easing.quad) }).toFixed(4)})` }} /> : null;
  if (kind === "split") {
    const c = t < at ? interpolate(t, [at - d, at], [0, 1], { ...cl, easing: OUT }) : 1 - interpolate(t, [at, at + d], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
    return (
      <>
        <div style={{ position: "absolute", left: 0, top: 0, width: 964, height: 1080, background: color, borderRight: `12px solid ${edge}`, boxSizing: "border-box", transform: `translateX(${((c - 1) * 990).toFixed(0)}px)` }} />
        <div style={{ position: "absolute", left: 956, top: 0, width: 964, height: 1080, background: color, borderLeft: `12px solid ${edge}`, boxSizing: "border-box", transform: `translateX(${((1 - c) * 990).toFixed(0)}px)` }} />
      </>
    );
  }
  const x = (lin(t, at - d, at + d) * 2 - 1) * 3300 * dir;
  return <div style={{ position: "absolute", left: 960 - 1400, top: -200, width: 2800, height: 1480, background: color, transform: `translateX(${x.toFixed(0)}px) skewX(${-20 * dir}deg)`, boxShadow: `${26 * dir}px 0 0 ${edge}, ${-26 * dir}px 0 0 ${edge}` }} />;
};
const Scene: React.FC<{ t: number; a: number; b: number; theme: ThemeKey; children: React.ReactNode }> = ({ t, a, b, theme, children }) => {
  if (t < a || t >= b) return null;
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Bg t={t} theme={theme} />
      {children}
    </AbsoluteFill>
  );
};
const Balloon: React.FC<{ t: number; x: number; y: number; s: number; c: string; i: number }> = ({ t, x, y, s, c, i }) => (
  <svg width={s} height={s * 1.7} viewBox="0 0 60 102" style={{ position: "absolute", left: x + Math.sin(t * 0.9 + i) * 10, top: y + Math.sin(t * 1.3 + i * 2) * 16 }}>
    <path d="M30 78 q-8 10 2 22" fill="none" stroke={c} strokeWidth={2.500} />
    <ellipse cx={30} cy={40} rx={28} ry={38} fill={c} />
    <ellipse cx={20} cy={26} rx={5} ry={10} fill="rgba(255,255,255,0.4)" />
  </svg>
);
// boneco dançando (bloco de ritmos)
const Dancer: React.FC<{ t: number; x: number; y: number; s: number; ph: number }> = ({ t, x, y, s, ph }) => {
  const b = t * ((Math.PI * 2 * 124) / 60 / 2) + ph;
  const bob = Math.abs(Math.sin(b)) * 26;
  const P = (ax: number, ay: number, len: number, ang: number): [number, number] => [ax + Math.cos(ang) * len, ay + Math.sin(ang) * len];
  const hip: [number, number] = [0, -bob];
  const neck: [number, number] = [Math.sin(b) * 18, -250 - bob];
  const aL = P(neck[0], neck[1] + 20, 130, Math.PI * 1.22 + Math.sin(b) * 0.5);
  const aL2 = P(aL[0], aL[1], 120, Math.PI * 1.45 + Math.sin(b + 1) * 0.6);
  const aR = P(neck[0], neck[1] + 20, 130, -0.25 + Math.cos(b) * 0.5);
  const aR2 = P(aR[0], aR[1], 120, 0.5 + Math.sin(b + 2) * 0.7);
  const lL = P(hip[0], hip[1], 150, Math.PI * 0.62 + Math.sin(b) * 0.25);
  const lL2 = P(lL[0], lL[1], 150, Math.PI * 0.5 + Math.max(0, Math.sin(b)) * 0.5);
  const lR = P(hip[0], hip[1], 150, Math.PI * 0.36 - Math.sin(b) * 0.25);
  const lR2 = P(lR[0], lR[1], 150, Math.PI * 0.5 - Math.max(0, -Math.sin(b)) * 0.5);
  const seg = (p: [number, number], q: [number, number], kkey: string) => <line key={kkey} x1={p[0]} y1={p[1]} x2={q[0]} y2={q[1]} stroke="url(#dg)" strokeWidth={44} strokeLinecap="round" />;
  return (
    <svg width={900} height={900} viewBox="-450 -520 900 900" style={{ position: "absolute", left: x - 450 * s, top: y - 520 * s, width: 900 * s, height: 900 * s, filter: "drop-shadow(0 0 24px rgba(255,90,140,0.55))", overflow: "visible" }}>
      <defs>
        <linearGradient id="dg" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#FF2D8E" />
          <stop offset="1" stopColor="#FFB000" />
        </linearGradient>
      </defs>
      {seg(hip, neck, "t")}
      {seg([neck[0], neck[1] + 20], aL, "a1")}
      {seg(aL, aL2, "a2")}
      {seg([neck[0], neck[1] + 20], aR, "a3")}
      {seg(aR, aR2, "a4")}
      {seg(hip, lL, "l1")}
      {seg(lL, lL2, "l2")}
      {seg(hip, lR, "l3")}
      {seg(lR, lR2, "l4")}
      <circle cx={neck[0] + Math.sin(b) * 6} cy={neck[1] - 62} r={44} fill="url(#dg)" />
    </svg>
  );
};

