        <div style={{ position: "absolute", left: 0, right: 0, top: 250, display: "flex", justifyContent: "center", ...zoom(t, B.fim + 0.5) }}>
          <Logo w={980} />
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 690, display: "flex", justifyContent: "center" }}>
          <div style={{ background: WHITE, transform: `skewX(-8deg) scaleX(${k(t, B.fim + 1.6, 0.5).toFixed(3)})`, padding: "12px 44px 18px" }}>
            <div style={{ ...it(64, RED), transform: "skewX(8deg)", opacity: lin(t, B.fim + 1.9, B.fim + 2.1) }}>Torne-se sua melhor versão!</div>
          </div>
        </div>
      </Scene>

      {CUTS.map(([at, color, edge, kind], i) => (
        <Cut key={i} t={t} at={at} i={i} color={color} edge={edge} kind={kind} />
      ))}
      {/* começo e fim em preto, para a repetição emendar */}
      {t < 0.5 ? <AbsoluteFill style={{ background: "#000", opacity: 1 - t / 0.5 }} /> : null}
      {t > 299.2 ? <AbsoluteFill style={{ background: "#000", opacity: (t - 299.2) / 0.8 }} /> : null}
    </AbsoluteFill>
  );
};

